/*updateBuyerWmGrWarehousingLisGrdt*/
UPDATE ICOMGRDT A
SET 
	  A.STATUS         = 'D'
	, A.SEND_DATE      = ' '
	, A.SEND_TIME      = ' '
	, A.CHANGE_DATE    = TO_CHAR(SYSDATE,'YYYYMMDD')
	, A.CHANGE_TIME    = TO_CHAR(SYSDATE,'HH24MISS')
	, A.CHANGE_USER_ID = #{user_id}
WHERE
		A.BUYER   = #{com_code}
	AND A.GR_NO   = #{gr_no}
	AND A.GR_SEQ  = #{gr_seq}


/*updateBuyerWmGrWarehousingLisPodt*/
UPDATE ICOMPODT
SET 
	GR_QTY = NVL(GR_QTY,0) - NVL( ${gr_qty} , 0)
WHERE 
		BUYER   = #{com_code}
	AND PO_NO   = #{po_no}
	AND PO_SEQ  = #{po_seq}


/*updateBuyerWmGrWarehousingLisIvdt*/
UPDATE ICOMIVDT A
SET
	A.GR_QTY = DECODE((	SELECT B.PROCESS_TYPE 
						FROM ICOMGRDT B
						WHERE 	B.BUYER = #{com_code}
							AND B.GR_NO = #{gr_no}
							AND B.GR_SEQ = #{gr_seq}
				),'0', 0 , 'G1', 0, A.GR_QTY)
WHERE
		A.BUYER 	= #{com_code}
	AND A.INV_NO 	= #{inv_no}
	AND A.INV_SEQ 	= #{inv_seq}
	AND A.STATUS	<>'D'


/*updateBuyerWmGrWarehousingLisIvhd*/
UPDATE ICOMIVHD
SET GR_DATE = ''
WHERE 
		BUYER   = #{com_code}
	AND INV_NO  = #{inv_no}


/*updateBuyerWmGrWarehousingLisWmsIvdt1*/
UPDATE WMSIVDT A 
SET
	  A.BUYER_GR_QTY = 0
	, A.CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
	, A.CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
WHERE 
		A.BUYER  = #{com_code}
	AND A.WAREHOUSE_CODE = #{warehouse_code}
	AND A.SELLER   = 'KRKORE0001'
	AND A.PO_NO   = #{po_no}
	AND A.PO_SEQ  = #{po_seq}
	AND A.STATUS  != 'D'


/*updateBuyerWmGrWarehousingLisWmsIvdt2*/
UPDATE WMSIVDT A 
SET
	  A.BUYER_GR_QTY = 0
	, A.CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
	, A.CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
WHERE 
	A.BUYER  = #{com_code}
AND A.WAREHOUSE_CODE = #{warehouse_code}
AND A.SELLER   = 'KRKORE0001'
AND A.INV_NO   = #{inv_no}
AND A.INV_SEQ  = #{inv_seq}
AND A.STATUS  != 'D'

