/*selectBuyerWmGrWarehousingLisCloseList*/ SELECT TO_CHAR(TO_DATE(BILL_DATE,'YYYY-MM-DD'),'YYMM')||TO_CHAR(ROWNUM,'FM000000') AS F_NO , ADD_DATE , PR_NO , LEGACY_USER_ID , PO_NO , BILL_NO , GR_DATE , IRS_NO , IRS_NO_NAME , ITEM_QTY , UNIT_PRICE , ITEM_AMT , UNIT_MEASURE , PROCESS_ACCOUNT , ACCOUNT_TYPE , VAT_AMT , REMARK , BILL_DATE , PROCESS_HISTORY , BILL_CREATE_DATE , PROCESS_1 , IMSI_1 , VAT_1 , BUYER_ITEM_NO , DESCRIPTION , RECEIPTS_DIS , MG_ITEM1 , MG_ITEM2 , MG_ITEM3 , MG_ITEM4 , MG_ITEM5 , MG_ITEM6 , MG_ITEM7 , MG_ITEM8 , MG_ITEM9 , MG_ITEM10 , MG_GUBUN1 , MG_GUBUN2 , MG_GUBUN3 , MG_GUBUN4 , MG_GUBUN5 , MG_GUBUN6 , MG_GUBUN7 , MG_GUBUN8 , MG_GUBUN9 , MG_GUBUN10 , ITEM_NAME1 , ITEM_NAME2 , ITEM_NAME3 , ITEM_NAME4 , ITEM_NAME5 , ITEM_NAME6 , ITEM_NAME7 , ITEM_NAME8 , ITEM_NAME9 , ITEM_NAME10 , CASH_RECEIPT , APPROVAL_NO , RESEARCH_CODE , RESEARCH_NAME , SIZE_QTY , SIZE_LEN FROM ( SELECT NULL AS F_NO , TO_CHAR(TO_DATE(PRDT.ADD_DATE,'YYYYMMDD'),'YYYY-MM-DD') AS ADD_DATE , PRDT.PR_NO AS PR_NO , (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = PRDT.ADD_USER_ID) AS LEGACY_USER_ID , PODT.PO_NO AS PO_NO , NULL AS BILL_NO , TO_CHAR(TO_DATE(GRDT.GR_DATE,'YYYYMMDD'),'YYYY-MM-DD') AS GR_DATE , CMP.IRS_NO AS IRS_NO , CMP.COM_NAME_LOC AS IRS_NO_NAME , GRDT.ITEM_QTY AS ITEM_QTY , GRDT.UNIT_PRICE AS UNIT_PRICE , GRDT.ITEM_AMT AS ITEM_AMT , GRDT.UNIT_MEASURE AS UNIT_MEASURE , '25100' AS PROCESS_ACCOUNT , PRDT.ACCOUNT_TYPE AS ACCOUNT_TYPE , GRDT.ITEM_AMT/10 AS VAT_AMT , GRDT.ITEM_QTY||GRDT.UNIT_MEASURE||' '||GRDT.UNIT_PRICE||'원 '||GRDT.ITEM_AMT||'원' AS REMARK , TO_CHAR(LAST_DAY(TO_DATE(GRDT.GR_DATE,'YYYYMMDD')),'YYYY-MM-DD') AS BILL_DATE , NULL AS PROCESS_HISTORY , NULL AS BILL_CREATE_DATE , NULL AS PROCESS_1 , NULL AS IMSI_1 , NULL AS VAT_1 , GRDT.BUYER_ITEM_NO AS BUYER_ITEM_NO , GRDT.DESCRIPTION AS DESCRIPTION , NULL AS RECEIPTS_DIS , CASE WHEN F_SPLIT(MG_CODE,CHR(38),1) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),1)) WHEN F_SPLIT(MG_CODE,CHR(38),1) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),1) END AS MG_ITEM1 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),2) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),2)) WHEN F_SPLIT(MG_CODE,CHR(38),2) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),2) END AS MG_ITEM2 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),3) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),3)) WHEN F_SPLIT(MG_CODE,CHR(38),3) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),3) END AS MG_ITEM3 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),4) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),4)) WHEN F_SPLIT(MG_CODE,CHR(38),4) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),4) END AS MG_ITEM4 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),5) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),5)) WHEN F_SPLIT(MG_CODE,CHR(38),5) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),5) END AS MG_ITEM5 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),6) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),6)) WHEN F_SPLIT(MG_CODE,CHR(38),6) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),6) END AS MG_ITEM6 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),7) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),7)) WHEN F_SPLIT(MG_CODE,CHR(38),7) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),7) END AS MG_ITEM7 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),8) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),8)) WHEN F_SPLIT(MG_CODE,CHR(38),8) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),8) END AS MG_ITEM8 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),9) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),9)) WHEN F_SPLIT(MG_CODE,CHR(38),9) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),9) END AS MG_ITEM9 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),10) = 'A04' THEN (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = F_SPLIT(MG_NOTE,CHR(38),10)) WHEN F_SPLIT(MG_CODE,CHR(38),10) = 'DEV' THEN NULL ELSE F_SPLIT(MG_NOTE,CHR(38),10) END AS MG_ITEM10
, CASE WHEN F_SPLIT(MG_CODE,CHR(38),1) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),1) END AS MG_GUBUN1 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),2) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),2) END AS MG_GUBUN2 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),3) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),3) END AS MG_GUBUN3 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),4) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),4) END AS MG_GUBUN4 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),5) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),5) END AS MG_GUBUN5 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),6) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),6) END AS MG_GUBUN6 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),7) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),7) END AS MG_GUBUN7 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),8) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),8) END AS MG_GUBUN8 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),9) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),9) END AS MG_GUBUN9 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),10) = 'DEV' THEN NULL ELSE F_SPLIT(MG_CODE,CHR(38),10) END AS MG_GUBUN10
, CASE WHEN F_SPLIT(MG_CODE,CHR(38),1) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),1)) WHEN F_SPLIT(MG_CODE,CHR(38),1) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),1)) WHEN F_SPLIT(MG_CODE,CHR(38),1) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),1) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),1) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),1)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),1) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),1)) END AS ITEM_NAME1 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),2) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),2)) WHEN F_SPLIT(MG_CODE,CHR(38),2) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),2)) WHEN F_SPLIT(MG_CODE,CHR(38),2) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),2) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),2) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),2)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),2) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),2)) END AS ITEM_NAME2 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),3) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),3)) WHEN F_SPLIT(MG_CODE,CHR(38),3) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),3)) WHEN F_SPLIT(MG_CODE,CHR(38),3) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),3) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),3) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),3)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),3) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),3)) END AS ITEM_NAME3 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),4) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),4)) WHEN F_SPLIT(MG_CODE,CHR(38),4) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),4)) WHEN F_SPLIT(MG_CODE,CHR(38),4) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),4) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),4) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),4)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),4) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),4)) END AS ITEM_NAME4 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),5) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),5)) WHEN F_SPLIT(MG_CODE,CHR(38),5) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),5)) WHEN F_SPLIT(MG_CODE,CHR(38),5) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),5) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),5) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),5)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),5) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),5)) END AS ITEM_NAME5 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),6) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),6)) WHEN F_SPLIT(MG_CODE,CHR(38),6) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),6)) WHEN F_SPLIT(MG_CODE,CHR(38),6) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),6) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),6) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),6)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),6) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),6)) END AS ITEM_NAME6 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),7) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),7)) WHEN F_SPLIT(MG_CODE,CHR(38),7) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),7)) WHEN F_SPLIT(MG_CODE,CHR(38),7) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),7) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),7) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),7)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),7) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),7)) END AS ITEM_NAME7 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),8) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),8)) WHEN F_SPLIT(MG_CODE,CHR(38),8) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),8)) WHEN F_SPLIT(MG_CODE,CHR(38),8) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),8) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),8) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),8)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),8) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),8)) END AS ITEM_NAME8 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),9) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),9)) WHEN F_SPLIT(MG_CODE,CHR(38),9) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),9)) WHEN F_SPLIT(MG_CODE,CHR(38),9) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),9) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),9) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),9)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),9) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),9)) END AS ITEM_NAME9 , CASE WHEN F_SPLIT(MG_CODE,CHR(38),10) = 'A03' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'C001' AND CODE = F_SPLIT(MG_NOTE,CHR(38),10)) WHEN F_SPLIT(MG_CODE,CHR(38),10) = 'A04' THEN (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = GRDT.BUYER AND USER_ID = F_SPLIT(MG_NOTE,CHR(38),10)) WHEN F_SPLIT(MG_CODE,CHR(38),10) = 'D03' THEN TO_CHAR(PODT.UNIT_PRICE) WHEN F_SPLIT(MG_CODE,CHR(38),10) = 'D68' THEN TO_CHAR(PODT.ITEM_QTY) WHEN F_SPLIT(MG_CODE,CHR(38),10) = 'B27' THEN (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = GRDT.BUYER AND TYPE = 'Z014' AND CODE = F_SPLIT(MG_NOTE,CHR(38),10)) ELSE (SELECT TEXT1 FROM ICOMCOD3 WHERE BUYER = GRDT.BUYER AND TYPE = 'MTOC' AND CODE1 = F_SPLIT(MG_CODE,CHR(38),10) AND CODE2 = F_SPLIT(MG_NOTE,CHR(38),10)) END AS ITEM_NAME10 , NULL AS CASH_RECEIPT , NULL AS APPROVAL_NO , (SELECT B.CODE2 FROM ICOMCOD3 A, ICOMCOD3 B WHERE A.BUYER = PRDT.BUYER AND A.CODE2 = 'DEV' AND A.TYPE = 'ATOM' AND A.CODE1 = PRDT.ACCOUNT_TYPE AND B.BUYER = PRDT.BUYER AND B.TYPE = 'MTOC' AND B.CODE1 = 'DEV' AND B.CODE2 = F_SPLIT(PRDT.MG_NOTE,CHR(38),A.VALUE1)) AS RESEARCH_CODE , (SELECT B.TEXT1 FROM ICOMCOD3 A, ICOMCOD3 B WHERE A.BUYER = PRDT.BUYER AND A.CODE2 = 'DEV' AND A.TYPE = 'ATOM' AND A.CODE1 = PRDT.ACCOUNT_TYPE AND B.BUYER = PRDT.BUYER AND B.TYPE = 'MTOC' AND B.CODE1 = 'DEV' AND B.CODE2 = F_SPLIT(PRDT.MG_NOTE,CHR(38),A.VALUE1)) AS RESEARCH_NAME , PRDT.SIZE_QTY , PRDT.SIZE_LEN FROM ICOMGRDT GRDT, ICOMPODT PODT, ICOMPRDT PRDT, (SELECT COM_NAME_LOC, IRS_NO FROM ICOMCMPY WHERE COM_CODE = 'KRKORE0001') CMP WHERE GRDT.BUYER = #{st_com_code} AND GRDT.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PODT.REF_PR_NO LIKE #{st_ref_pr_no}||'%'
AND GRDT.INV_NO LIKE UPPER(#{st_search_no}||'%')
AND PODT.PO_NO LIKE UPPER(#{st_search_no}||'%')
AND PRDT.PURCHASER_DEPT = #{st_req_dept_code}
AND PRDT.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PRDT.PURCHASER_ID = #{st_po_user_id}
AND PRDT.ADD_USER_ID = #{st_po_user_id}
AND GRDT.STATUS ^= 'D' AND GRDT.BUYER = PODT.BUYER AND GRDT.PO_NO = PODT.PO_NO AND GRDT.PO_SEQ= PODT.PO_SEQ AND PODT.STATUS ^= 'D' AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ= PRDT.PR_SEQ ORDER BY PRDT.BUYER, PRDT.PR_NO, PRDT.PR_SEQ, GRDT.GR_NO, GRDT.GR_SEQ )

/*selectBuyerWmGrWarehousingLisCloseType2List*/ SELECT DENSE_RANK() OVER (ORDER BY grdt.gr_date,prdt.add_user_dept,GRDT.GR_NO,GRDT.GR_SEQ) RNUM -- 항목 , GRDT.GR_DATE -- 입고일자 , NVL(trim(PRDT.REF_PR_NO),PRDT.ADD_USER_DEPT) AS CC_DEPT -- 코스트센터 , PODT.ACCOUNT_TYPE -- 계정 , PODT.BUDGET_DEPT -- 예산부서 , PODT.BUYER_ITEM_NO -- 자재번호 , PODT.DESCRIPTION -- 자재내역 , GRDT.ITEM_QTY -- 수량 , GRDT.ITEM_AMT -- 금액 , PRDT.ADD_USER_DEPT -- 요청부서 , (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE COM_CODE = PRDT.BUYER AND USER_ID = PRDT.ADD_USER_ID) AS ADD_USER_ID --요청자 , (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE COM_CODE = PRDT.BUYER AND USER_ID = PRDT.PURCHASER_ID) AS PURCHASER_ID --구매담당자 , TRUNC((DENSE_RANK() OVER (ORDER BY grdt.gr_date,prdt.add_user_dept,GRDT.GR_NO,GRDT.GR_SEQ)-1)/10)+1 BILL_FLAG --세금계산서구분 FROM ICOMGRDT GRDT, ICOMPODT PODT, ICOMPRDT PRDT WHERE 1=1 AND GRDT.BUYER = #{st_com_code} AND GRDT.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PODT.REF_PR_NO LIKE #{st_ref_pr_no}||'%'
AND GRDT.INV_NO LIKE UPPER(#{st_search_no}||'%')
AND PODT.PO_NO LIKE UPPER(#{st_search_no}||'%')
AND PRDT.PURCHASER_DEPT = #{st_req_dept_code}
AND PRDT.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PRDT.PURCHASER_ID = #{st_po_user_id}
AND PRDT.ADD_USER_ID = #{st_po_user_id}
AND GRDT.STATUS != 'D' AND GRDT.BUYER = PODT.BUYER AND GRDT.PO_NO = PODT.PO_NO AND GRDT.PO_SEQ= PODT.PO_SEQ AND PODT.STATUS != 'D' AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ= PRDT.PR_SEQ AND PRDT.STATUS != 'D'

/*selectBuyerWmGrWarehousingLisType1List*/ SELECT DECODE(GR.CLOSE_FLAG,'Y','마감완료', DECODE((NVL(PO.ITEM_QTY,0) - NVL(PO.GR_QTY,0)),0,'입고완료','부분입고')) AS GR_STATUS --1상태 , PH.PO_CREATE_DATE --2발주일 , PO.PO_NO --3발주번호 , GR.GR_NO --4입고번호 , PO.BUYER_ITEM_NO --5제품코드 , PO.REF_PR_NO --6관리번호 , PO.DESCRIPTION --7품명 , PO.SPECIFICATION --8규격 , PO.UNIT_MEASURE --9단위 , PO.ITEM_QTY --10발주수량 , PO.UNIT_PRICE --11단가 , GR.ITEM_AMT --12입고금액 , PO.GR_QTY --13총입고수량 , GR.ITEM_QTY AS ITEM_QTY1 --14입고수량 , GR.GR_DATE --15입고일 , PH.PURCHASER_NAME --16발주자 , DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = PH.BUYER), 'N', '코리아이플랫폼(주)' , (SELECT DECODE(AGENT_OPEN_FLAG,'N', '코리아이플랫폼(주)', COM_NAME_LOC) FROM ICOMCMPY WHERE COM_CODE = GR.AGENT AND STATUS !='D')) AS AGENT_NAME --17공급사 , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.CHANGE_USER_DEPT AND TYPE = 'C001') AS REQ_DEPT_NAME --18요청부서 , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE COM_CODE = PR.BUYER AND USER_ID = PR.CHANGE_USER_ID) AS REQ_USER_NAME --19요청자 , PR.CHANGE_USER_DEPT --20요청부서코드 , PO.CATEG_ID --21카테고리ID , (SELECT TEXT1||'['||CODE||']' FROM ICOMCOD2 WHERE COMPANY_CODE = PO.BUYER AND TYPE = 'P001' AND CODE = DECODE(NVL(PO.REF_PR_NO,''),'','',SUBSTR(PO.REF_PR_NO,0,2))) AS PLANT_TEXT , (SELECT TEXT1||'['||CODE||']' FROM ICOMCOD2 WHERE COMPANY_CODE = PO.BUYER AND TYPE = 'P002' AND CODE = DECODE(NVL(PO.REF_PR_NO,''),'','',SUBSTR(PO.REF_PR_NO,3,4))) AS COST_CENTER_TEXT , (SELECT TEXT1||'['||CODE||']' FROM ICOMCOD2 WHERE COMPANY_CODE = PO.BUYER AND TYPE = 'M014' AND CODE = DECODE(NVL(PO.REF_PR_NO,''),'','',SUBSTR(PO.REF_PR_NO,7,8))) AS ACCOUNT_TEXT , (SELECT (SELECT LUSR.USER_NAME_LOC FROM ICOGPASSLN PASS,ICOMLUSR LUSR WHERE PASS.COMPANY = DOCU.COMPANY AND PASS.DOCU_NO = DOCU.DOCU_NO AND PASS.PASS_TP='1' AND PASS.ORDER_NO = '2' AND PASS.USER_ID = LUSR.USER_ID) || (SELECT LUSR.USER_NAME_LOC FROM ICOGPASSLN PASS,ICOMLUSR LUSR WHERE PASS.COMPANY = DOCU.COMPANY AND PASS.DOCU_NO = DOCU.DOCU_NO AND PASS.PASS_TP='1' AND PASS.ORDER_NO = '3' AND PASS.USER_ID = LUSR.USER_ID) || (SELECT LUSR.USER_NAME_LOC FROM ICOGPASSLN PASS,ICOMLUSR LUSR WHERE PASS.COMPANY = DOCU.COMPANY AND PASS.DOCU_NO = DOCU.DOCU_NO AND PASS.PASS_TP='1' AND PASS.ORDER_NO = '4' AND PASS.USER_ID = LUSR.USER_ID) FROM ICOMTRGW TRGW, ICOGDOCU DOCU WHERE TRGW.COM_CODE = PO.BUYER AND TRGW.KEY_1 = PO.PR_NO AND TRGW.COM_CODE = DOCU.COMPANY AND TRGW.TARGET = DOCU.DOCU_NO ) AS PASS_USER_NM , (SELECT REPLACE(REPLACE(DOCU.DOCU_CONT, CHR(13),' '),CHR(10),' ') FROM ICOMTRGW TRGW, ICOGDOCU DOCU WHERE TRGW.COM_CODE = PO.BUYER AND TRGW.KEY_1 = PO.PR_NO AND TRGW.COM_CODE = DOCU.COMPANY AND TRGW.TARGET = DOCU.DOCU_NO ) AS PASS_DOC_NM FROM ICOMPODT PO, ICOMPOHD PH, ICOMGRDT GR, ICOMPRDT PR WHERE PO.BUYER = #{st_com_code} AND GR.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PO.PO_NO LIKE UPPER(#{st_search_no}||'%')
AND PO.REF_PR_NO LIKE #{st_ref_pr_no}||'%'
AND PH.ADD_USER_ID = #{st_po_user_id}
AND PR.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PO.BUYER = PH.BUYER AND PO.PO_NO = PH.PO_NO AND PO.BUYER = GR.BUYER AND PO.PO_NO = GR.PO_NO AND PO.PO_SEQ = GR.PO_SEQ AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND PO.STATUS <>'D' AND PH.STATUS <>'D' AND GR.STATUS <>'D' AND PR.STATUS <>'D' ORDER BY PO.PO_NO, GR.GR_NO, GR.GR_SEQ

