AND PO.PO_NO LIKE UPPER(#{st_search_no}||'%')
AND PO.REF_PR_NO LIKE #{st_ref_pr_no}||'%'
AND PH.ADD_USER_ID = #{st_po_user_id}
AND PR.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PO.BUYER = PH.BUYER AND PO.PO_NO = PH.PO_NO AND PO.BUYER = GR.BUYER AND PO.PO_NO = GR.PO_NO AND PO.PO_SEQ = GR.PO_SEQ AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND PO.STATUS <>'D' AND PH.STATUS <>'D' AND GR.STATUS <>'D' AND PR.STATUS <>'D' ORDER BY PO.PO_NO, GR.GR_NO, GR.GR_SEQ

