AND PR.PURCHASER_DEPT = #{st_req_dept_code}
AND PR.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PR.BUDGET_DEPT = #{st_req_dept_code}
AND EXISTS ( SELECT 'X' FROM ICOMIVDT IV, WMSIVDT WMS WHERE IV.BUYER = PO.BUYER AND IV.PO_NO = PO.PO_NO AND IV.PO_SEQ= PO.PO_SEQ AND IV.STATUS != 'D' AND IV.BUYER = WMS.BUYER(+) AND IV.PO_NO = WMS.PO_NO(+) AND IV.PO_SEQ= WMS.PO_SEQ(+) AND IV.INV_NO = WMS.S_INV_NO(+) AND IV.INV_SEQ= WMS.S_INV_SEQ(+) AND WMS.STATUS(+) <> 'D' AND DECODE(PO.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) LIKE UPPER('%'||#{st_search_no}||'%'))
AND PO.PO_NO LIKE UPPER(#{st_search_no}||'%')
AND PR.PURCHASER_ID = #{st_po_user_id}
AND PR.ADD_USER_ID = #{st_po_user_id}
AND GR.BUYER_ITEM_NO LIKE '%'||#{st_search_buyer_item_no}||'%'
AND (GR.DESCRIPTION LIKE '%'||#{st_search_desc_spec}||'%' OR GR.SPECIFICATION LIKE '%'||#{st_search_desc_spec}||'%')
AND GR.AGENT IN (SELECT COM_CODE FROM ICOMCMPY WHERE COM_NAME_LOC LIKE '%'||#{st_search_agent}||'%' AND STATUS IN ('C','R') AND BUSINESS_COND='S')
AND PO.BUYER = PH.BUYER AND PO.PO_NO = PH.PO_NO AND PO.BUYER = GR.BUYER AND PO.PO_NO = GR.PO_NO AND PO.PO_SEQ = GR.PO_SEQ AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND PO.BUYER = BUYER.COM_CODE(+) AND PO.STATUS <>'D' AND PH.STATUS <>'D' AND GR.STATUS <>'D' AND PR.STATUS <>'D' ORDER BY PO.PO_NO, GR.GR_NO, GR.GR_SEQ ) S

/* selectBuyerWmGrWarehousingLisType5List_v3 */ SELECT S.GR_STATUS -- 1 상태 , S.PO_CREATE_DATE -- 2 발주일 , S.PO_NO -- 3 발주번호 , S.GR_NO -- 4 입고번호 , S.BUYER_ITEM_NO -- 5 품목코드 , S.REF_PR_NO -- 6 관리번호 , S.DESCRIPTION -- 7 품명 , S.SPECIFICATION -- 8 규격 , S.UNIT_PRICE -- 9 단가 , S.ITEM_AMT -- 10 입고금액 , S.UNIT_MEASURE -- 11 단위 , S.PO_ITEM_QTY -- 12 발주수량 , S.GR_ITEM_QTY -- 13 입고수량 , S.GR_QTY -- 14 입고총수량 , S.GR_DATE -- 15 입고일 , S.PO_CREATOR -- 16 발주자 , DECODE(( SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = S.BUYER),'N','코리아이플랫폼(주)',S.AGENT_NAME) AS AGENT_NAME -- 17 공급사 , S.REQ_DEPT_NAME -- 18 요청부서 , S.GR_SEQ -- 19 , S.PO_SEQ -- 20 , S.INV_NO -- 21 , S.INV_SEQ -- 22 , S.IV_EXIST -- 23 , S.BUYER -- 24 , S.BYIT_COMORG_CODE -- 25 , S.CONTRACT_NO -- 26 , S.CONTRACT_SEQ -- 27 , S.PR_NO -- 28 , S.AGENT -- 29 , S.CHANGE_USER_DEPT -- 30 , DECODE(( SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = S.BUYER),'N','KRKORE0001',S.AGENT) AS AGENT_CODE -- 31 , S.CLOSE_FLAG -- 32 , S.AR_BILL_FLAG -- 33 , S.REF_PR_NO_TEXT -- 35 , ( SELECT CARD_USE_FLAG FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_USE_FLAG --36 , ( SELECT CARD_CONFIRM_NO FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_CONFIRM_NO -- 37 , S.PX_NO , S.CATEG_ID , S.BUDGET_DEPT , S.ACCOUNT_NAME , S.ADD_USER_NAME , S.CATEG_NAME , S.SO_CA_GUBUN , S.RECV_FLAG , S.CLSD_FLAG , S.PCO_REF_PR_NO , S.PCO_LEGACY_PO_NO , S.PR_CHANGE_DATE , S.GR_ADD_USER_ID , S.GR_ADD_USER_NAME , S.SIZE_QTY , S.SIZE_LEN , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE =S.BUYER) COM_NAME_LOC , S.PR_REF_PR_NO1 , S.PR_REF_PR_NO2 , S.PR_REF_PR_NO3 , S.PR_REF_PR_NO4 , S.IMAGE_KEY_INV , S.IMAGE_KEY_SIGN , S.PARCEL_INFO , S.AUTO_GR_FLAG , S.PROCESS_TYPE_NM , S.ADD_LEGACY_USER_ID , F_GET_APRV_USER_LIST(S.BUYER, S.SAVE_FLAG, S.PX_NO, '2') AS APRV_PATH -- 1: ID, 2: 사번 , S.INVOICE_DATE , S.DELIVERY_DATE FROM ( SELECT DISTINCT DECODE(GR.AR_BILL_FLAG,'Y','마감완료', DECODE((NVL(PO.ITEM_QTY,0) - NVL(PO.GR_QTY,0)),0,'입고완료','부분입고')) AS GR_STATUS , PH.PO_CREATE_DATE , PO.PO_NO , GR.GR_NO , PO.BUYER_ITEM_NO , PO.REF_PR_NO||DECODE(PO.BUYER,'KRDAEW0016','-'||TO_NUMBER(PO.LEGACY_PO_SEQ),'KRDUPO0001',PO.LEGACY_PO_NO,'') AS REF_PR_NO , PO.DESCRIPTION , PO.SPECIFICATION , PO.UNIT_PRICE , GR.ITEM_AMT , PO.UNIT_MEASURE , PO.ITEM_QTY AS PO_ITEM_QTY , GR.ITEM_QTY AS GR_ITEM_QTY , PO.GR_QTY , GR.GR_DATE , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.PURCHASER_ID) AS PO_CREATOR , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = GR.AGENT AND STATUS !='D') AS AGENT_NAME , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.CHANGE_USER_DEPT AND TYPE = 'C001') AS REQ_DEPT_NAME , GR.GR_SEQ , GR.PO_SEQ , GR.INV_NO , GR.INV_SEQ , DECODE(GR.INV_NO,NULL,'N','Y') AS IV_EXIST , PO.BUYER , PO.BYIT_COMORG_CODE , PO.CONTRACT_NO , PO.CONTRACT_SEQ , PO.PR_NO , PH.AGENT , PR.CHANGE_USER_DEPT , GR.CLOSE_FLAG , GR.AR_BILL_FLAG , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PO.BUYER AND TYPE = 'M014' AND CODE = PO.REF_PR_NO) AS REF_PR_NO_TEXT , PR.REF_NO AS PX_NO , PO.CATEG_ID , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.BUDGET_DEPT AND TYPE = 'C001') AS BUDGET_DEPT , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE = 'Z014' AND CODE = PR.ACCOUNT_TYPE) AS ACCOUNT_NAME , PR.ADD_USER_NAME , (SELECT CATEG_PATH FROM ICOMBYCA WHERE COM_CODE = PO.BYIT_COMORG_CODE AND STD_CATEG_ID = PO.CATEG_ID) AS CATEG_NAME , DECODE(( SELECT COUNT(*) FROM KEPRQDT WHERE BUYER = PO.BUYER AND BUYER_ITEM_NO = PO.BUYER_ITEM_NO AND SO_CA_FLAG = 'SO' AND STATUS ^='D'), 0, 'CA', 'SO') AS SO_CA_GUBUN , PR.RECV_FLAG , NVL(PO.CLSD_FLAG,'N') AS CLSD_FLAG , PR.REF_PR_NO AS PCO_REF_PR_NO , PO.LEGACY_PO_NO AS PCO_LEGACY_PO_NO , PR.CHANGE_DATE AS PR_CHANGE_DATE , GR.ADD_USER_ID AS GR_ADD_USER_ID , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = GR.ADD_USER_ID) AS GR_ADD_USER_NAME , PR.SIZE_QTY , PR.SIZE_LEN , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 1) AND FLAG = 'Y') AS PR_REF_PR_NO1 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 2) AND FLAG = 'Y') AS PR_REF_PR_NO2 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'Z014' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 3) AND FLAG = 'Y') AS PR_REF_PR_NO3 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'M014' AND COMPANY_CODE = PR.BUYER AND CODE = F_SPLIT(PR.REF_PR_NO, '^', 4) AND FLAG = 'Y') AS PR_REF_PR_NO4 , CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT IVHD.IMAGE_KEY_INV FROM ICOMIVHD IVHD WHERE IVHD.BUYER = GR.BUYER AND IVHD.INV_NO = GR.INV_NO AND IVHD.STATUS != 'D') ELSE (SELECT WMS.IMAGE_KEY_INV FROM WMSIVDT WMS WHERE WMS.BUYER = GR.BUYER AND WMS.INV_NO = GR.INV_NO AND WMS.INV_SEQ = GR.INV_SEQ AND WMS.STATUS != 'D') END AS IMAGE_KEY_INV , CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT IVHD.IMAGE_KEY_SIGN FROM ICOMIVHD IVHD WHERE IVHD.BUYER = GR.BUYER AND IVHD.INV_NO = GR.INV_NO AND IVHD.STATUS != 'D') ELSE (SELECT WMS.IMAGE_KEY_SIGN FROM WMSIVDT WMS WHERE WMS.BUYER = GR.BUYER AND WMS.INV_NO = GR.INV_NO AND WMS.INV_SEQ = GR.INV_SEQ AND WMS.STATUS != 'D') END AS IMAGE_KEY_SIGN , CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT F_GET_CMCD_NAME('C019', IVHD.PARCEL_COM_CODE) FROM ICOMIVHD IVHD WHERE IVHD.BUYER = GR.BUYER AND IVHD.INV_NO = GR.INV_NO AND IVHD.STATUS != 'D') ELSE (SELECT F_GET_CMCD_NAME('C019', WMS.DELIVERY_COMPANY) FROM WMSIVDT WMS WHERE WMS.BUYER = GR.BUYER AND WMS.INV_NO = GR.INV_NO AND WMS.INV_SEQ = GR.INV_SEQ AND WMS.STATUS != 'D') END AS PARCEL_INFO , NVL(BUYER.AUTO_GR_FLAG, 'N') AS AUTO_GR_FLAG , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = PO.PROCESS_TYPE AND FLAG = 'Y') AS PROCESS_TYPE_NM , (SELECT LEGACY_USER_ID FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS ADD_LEGACY_USER_ID , PR.SAVE_FLAG , CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT IVDT.INVOICE_DATE FROM ICOMIVDT IVDT WHERE IVDT.BUYER = GR.BUYER AND IVDT.INV_NO = GR.INV_NO AND IVDT.INV_SEQ = GR.INV_SEQ AND IVDT.STATUS != 'D') ELSE (SELECT WMS.INV_DATE FROM WMSIVDT WMS WHERE WMS.BUYER = GR.BUYER AND WMS.INV_NO = GR.INV_NO AND WMS.INV_SEQ = GR.INV_SEQ AND WMS.STATUS != 'D') END AS INVOICE_DATE , CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT IVDT.DELIVERY_DATE FROM ICOMIVDT IVDT WHERE IVDT.BUYER = GR.BUYER AND IVDT.INV_NO = GR.INV_NO AND IVDT.INV_SEQ = GR.INV_SEQ AND IVDT.STATUS != 'D') ELSE (SELECT WMS.DELIVERY_DATE FROM WMSIVDT WMS WHERE WMS.BUYER = GR.BUYER AND WMS.INV_NO = GR.INV_NO AND WMS.INV_SEQ = GR.INV_SEQ AND WMS.STATUS != 'D') END AS DELIVERY_DATE FROM ICOMPODT PO, ICOMPOHD PH, ICOMGRDT GR, ICOMPRDT PR, KEP_BUYER_FLAG BUYER WHERE 1=1
AND GR.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND GR.BUYER = #{st_com_code}
AND GR.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')
AND GR.BUYER = #{st_com_code}
AND GR.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PR.CHANGE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND (PO.REF_PR_NO LIKE #{st_ref_pr_no}||'%' OR PO.LEGACY_PO_NO LIKE #{st_ref_pr_no}||'%')
AND PR.ACCOUNT_TYPE = #{st_acnt_cd}
AND PO.LEGACY_PO_NO LIKE #{st_legacy_po_no}||'%'
AND UPPER( PR.BUYER_ITEM_NO) LIKE UPPER(#{st_buyer_item_no}||'%')
AND PR.CHANGE_USER_ID = #{st_change_user_id}
AND PR.PURCHASER_DEPT = #{st_req_dept_code}
AND PR.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PR.BUDGET_DEPT = #{st_req_dept_code}
AND EXISTS ( SELECT 'X' FROM ICOMIVDT IV, WMSIVDT WMS WHERE IV.BUYER = PO.BUYER AND IV.PO_NO = PO.PO_NO AND IV.PO_SEQ= PO.PO_SEQ AND IV.STATUS != 'D' AND IV.BUYER = WMS.BUYER(+) AND IV.PO_NO = WMS.PO_NO(+) AND IV.PO_SEQ= WMS.PO_SEQ(+) AND IV.INV_NO = WMS.S_INV_NO(+) AND IV.INV_SEQ= WMS.S_INV_SEQ(+) AND WMS.STATUS(+) <> 'D' AND DECODE(PO.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) LIKE UPPER('%'||#{st_search_no}||'%'))
AND PO.PO_NO LIKE UPPER(#{st_search_no}||'%')
AND PR.PURCHASER_ID = #{st_po_user_id}
AND PR.ADD_USER_ID = #{st_po_user_id}
AND GR.BUYER_ITEM_NO LIKE '%'||#{st_search_buyer_item_no}||'%'
AND (GR.DESCRIPTION LIKE '%'||#{st_search_desc_spec}||'%' OR GR.SPECIFICATION LIKE '%'||#{st_search_desc_spec}||'%')
AND GR.AGENT IN (SELECT COM_CODE FROM ICOMCMPY WHERE COM_NAME_LOC LIKE '%'||#{st_search_agent}||'%' AND STATUS IN ('C','R') AND BUSINESS_COND='S')
AND PO.BUYER = PH.BUYER AND PO.PO_NO = PH.PO_NO AND PO.BUYER = GR.BUYER AND PO.PO_NO = GR.PO_NO AND PO.PO_SEQ = GR.PO_SEQ AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND PO.BUYER = BUYER.COM_CODE(+) AND PO.STATUS <>'D' AND PH.STATUS <>'D' AND GR.STATUS <>'D' AND PR.STATUS <>'D' ORDER BY PO.PO_NO, GR.GR_NO, GR.GR_SEQ ) S

