AND (GR.DESCRIPTION LIKE '%'||#{st_search_desc_spec}||'%' OR GR.SPECIFICATION LIKE '%'||#{st_search_desc_spec}||'%')
AND GR.AGENT IN (SELECT COM_CODE FROM ICOMCMPY WHERE COM_NAME_LOC LIKE '%'||#{st_search_agent}||'%' AND STATUS IN ('C','R') AND BUSINESS_COND='S')
AND PO.BUYER = PH.BUYER AND PO.PO_NO = PH.PO_NO AND PO.BUYER = GR.BUYER AND PO.PO_NO = GR.PO_NO AND PO.PO_SEQ = GR.PO_SEQ AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND PO.STATUS <>'D' AND PH.STATUS <>'D' AND GR.STATUS <>'D' AND PR.STATUS <>'D' AND PR.BUYER = COD4.BUYER(+) AND PR.REQ_DEPT = COD4.CODE1(+) AND COD4.TYPE(+) = 'DERP' AND COD4.FLAG(+) = 'Y' AND PR.BUYER = COD3.CODE1(+) AND SUBSTR(PR.BUYER_ITEM_NO, 0, 2) = COD3.CODE2(+) AND COD3.TYPE(+) = 'DERP' AND COD3.FLAG(+) = 'Y' ORDER BY PO.PO_NO, GR.GR_NO, GR.GR_SEQ


/*selectBuyerWmGrWarehousingLisCarStockGrdtCheck*/
SELECT COUNT(1) AS CNT
FROM CAR_STOCK_GRDT CAR
WHERE CAR.BUYER = #{com_code}
AND CAR.GR_NO = #{gr_no}
AND CAR.GR_SEQ = TO_CHAR(#{gr_seq},'FM000000')
AND STATUS != 'D'


/*selectBuyerWmGrWarehousingLisCarStockCheckQty*/
SELECT
	(GR_QTY-IV_QTY)-#{gr_qty} AS CHECK_QTY
FROM CAR_STOCK
WHERE BUYER = #{com_code}
AND BUYER_ITEM_NO = #{buyer_item_no}

mapper.update:

/*updateBuyerWmGrWarehousingLisCarStockMinus*/
UPDATE CAR_STOCK SET
GR_QTY = (GR_QTY-#{gr_qty})
,CHANGE_USER_ID = #{user_id}
,CHANGE_DATE = SYSDATE
WHERE BUYER = #{com_code}
AND BUYER_ITEM_NO = #{buyer_item_no}


/*updateBuyerWmGrWarehousingLisCarStockGrdt*/
UPDATE CAR_STOCK_GRDT SET
STATUS = 'D'
,CHANGE_USER_ID = #{user_id}
,CHANGE_DATE = SYSDATE
WHERE BUYER = #{com_code}
AND BUYER_ITEM_NO = #{buyer_item_no}
AND GR_NO = #{gr_no}
AND GR_SEQ = #{gr_seq}
AND STATUS != 'D'

