/*selectBuyerWmGrWarehousingLamAsnList*/ SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = S.BUYER) AS COM_NAME_LOC, S.INV_NO, S.INV_SEQ, DECODE((SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = S.BUYER), 'N', '코리아이플랫폼(주)', S.AGENT_NAME) AS AGENT_NAME, S.BUYER_ITEM_NO, S.CATEG_NAME, S.DESCRIPTION, S.SPECIFICATION, S.MAKER_NAME, S.INV_QTY, S.UNIT_MEASURE, S.UNIT_PRICE, S.ORIGIN_NAME, S.CUR, S.PO_TTL_AMT, S.PRE_GR_YN, S.FAST_PO_YN, S.PR_NO, S.PR_SEQ, S.PO_NO, S.PO_SEQ, S.PO_QTY, S.REF_PR_NO, S.PO_CREATE_DATE, S.RD_DATE, S.CD_DATE, S.STATUS_TEXT, S.INVOICE_DATE, '' AS DELIVERY_PERSON_NAME, '' AS DELIVERY_PERSON_PHONE, '' AS DELIVERY_CAR_NO, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'C019' AND CODE = S.PARCEL_COM_CODE) AS PARCEL_COM_NAME, S.PARCEL_INV_NO, S.GR_QTY, S.PO_CREATOR, S.REQ_DEPT_NAME, S.ADD_USER_TEL, TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI') AS TODAY_DATE, S.ADD_USER_NAME, S.ADD_USER_NAME_ENG, S.ADD_USER_EMAIL, '1052552' AS ASN_VENDOR_CODE FROM ( SELECT DISTINCT PO.BUYER, GR.INV_NO, GR.INV_SEQ, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = GR.AGENT) AS AGENT_NAME, PO.BUYER_ITEM_NO, (SELECT CATEG_PATH FROM ICOMBYCA WHERE COM_CODE = PO.BYIT_COMORG_CODE AND STD_CATEG_ID = PO.CATEG_ID) AS CATEG_NAME, PO.DESCRIPTION, PO.SPECIFICATION, PO.MAKER_NAME, GR.ITEM_QTY AS INV_QTY, PO.UNIT_MEASURE, PO.UNIT_PRICE, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = PO.ORIGIN_CODE) AS ORIGIN_NAME, PH.CUR, PO.ITEM_QTY * PO.UNIT_PRICE AS PO_TTL_AMT, DECODE(PH.DOC_TYPE, 'S', 'Y', 'N') AS PRE_GR_YN, DECODE(PH.DOC_TYPE, 'F', 'Y', 'N') AS FAST_PO_YN, PO.PR_NO, PO.PR_SEQ, PO.PO_NO, PO.PO_SEQ, PO.ITEM_QTY AS PO_QTY, PO.REF_PR_NO, PH.PO_CREATE_DATE, PR.RD_DATE, CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT MAX(DS_DATE) FROM ICOMPORS WHERE BUYER = PO.BUYER AND PO_NO = PO.PO_NO AND PO_SEQ = PO.PO_SEQ AND DS_DATE = PO.DS_DATE AND STATUS != 'D') ELSE (SELECT MAX(SCHEDULED_DATE) FROM WMSIVDT WHERE BUYER = PO.BUYER AND PO_NO = PO.PO_NO AND PO_SEQ = PO.PO_SEQ AND STATUS != 'D') END AS CD_DATE, DECODE(GR.AR_BILL_FLAG, 'Y', '마감완료', DECODE((NVL(PO.ITEM_QTY,0) - NVL(PO.GR_QTY,0)), 0, '입고완료', '부분입고')) AS STATUS_TEXT, DECODE(PO.PROCESS_TYPE, '0', (SELECT MIN(INVOICE_DATE) FROM ICOMIVDT WHERE BUYER = PO.BUYER AND PO_NO = PO.PO_NO AND PO_SEQ = PO.PO_SEQ AND STATUS <>'D'), (SELECT MIN(INV_DATE) FROM WMSIVDT WHERE BUYER = PO.BUYER AND PO_NO = PO.PO_NO AND PO_SEQ = PO.PO_SEQ AND STATUS <> 'D') ) AS INVOICE_DATE, CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT IVHD.PARCEL_COM_CODE FROM ICOMIVHD IVHD WHERE IVHD.BUYER = GR.BUYER AND IVHD.INV_NO = GR.INV_NO AND IVHD.STATUS != 'D') END AS PARCEL_COM_CODE, CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT IVHD.PARCEL_INV_NO FROM ICOMIVHD IVHD WHERE IVHD.BUYER = GR.BUYER AND IVHD.INV_NO = GR.INV_NO AND IVHD.STATUS != 'D') END AS PARCEL_INV_NO, PO.GR_QTY, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.PURCHASER_ID) AS PO_CREATOR, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.REQ_DEPT AND TYPE = 'C001') AS REQ_DEPT_NAME, PR.ADD_USER_TEL, GR.GR_NO, GR.GR_SEQ, PR.ADD_USER_NAME, (SELECT USER_NAME_ENG FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS ADD_USER_NAME_ENG, (SELECT EMAIL FROM ICOMLUSR WHERE USER_ID = PR.ADD_USER_ID) AS ADD_USER_EMAIL FROM ICOMPODT PO, ICOMPOHD PH, ICOMGRDT GR, ICOMPRDT PR WHERE 1=1
