AND PO.BUYER = PH.BUYER AND PO.PO_NO = PH.PO_NO AND PO.BUYER = GR.BUYER AND PO.PO_NO = GR.PO_NO AND PO.PO_SEQ = GR.PO_SEQ AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND PO.BUYER = BUYER.COM_CODE(+) AND PO.STATUS <>'D' AND PH.STATUS <>'D' AND GR.STATUS <>'D' AND PR.STATUS <>'D' ORDER BY PO.PO_NO, GR.GR_NO, GR.GR_SEQ ) S

/*selectBuyerWmGrWarehousingHanComLCLisList_v3*/ SELECT S.GR_STATUS -- 1 상태 , S.PO_CREATE_DATE -- 2 발주일 , S.PO_NO -- 3 발주번호 , S.GR_NO -- 4 입고번호 , S.BUYER_ITEM_NO -- 5 품목코드 , S.REF_PR_NO -- 6 관리번호 , S.DESCRIPTION -- 7 품명 , S.SPECIFICATION -- 8 규격 , S.UNIT_PRICE -- 9 단가 , S.ITEM_AMT -- 10 입고금액 , S.UNIT_MEASURE -- 11 단위 , S.PO_ITEM_QTY -- 12 발주수량 , S.GR_ITEM_QTY -- 13 입고수량 , S.GR_QTY -- 14 입고총수량 , S.GR_DATE -- 15 입고일 , S.PO_CREATOR -- 16 발주자 , DECODE(( SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = S.BUYER),'N','코리아이플랫폼(주)',S.AGENT_NAME) AS AGENT_NAME -- 17 공급사 , S.REQ_DEPT_NAME -- 18 요청부서 , S.GR_SEQ -- 19 , S.PO_SEQ -- 20 , S.INV_NO -- 21 , S.INV_SEQ -- 22 , S.IV_EXIST -- 23 , S.BUYER -- 24 , S.BYIT_COMORG_CODE -- 25 , S.CONTRACT_NO -- 26 , S.CONTRACT_SEQ -- 27 , S.PR_NO -- 28 , S.AGENT -- 29 , S.CHANGE_USER_DEPT -- 30 , DECODE(( SELECT AGENT_OPEN_FLAG FROM ICOMCMPY WHERE COM_CODE = S.BUYER),'N','KRKORE0001',S.AGENT) AS AGENT_CODE -- 31 , S.CLOSE_FLAG -- 32 , S.AR_BILL_FLAG -- 33 , ( SELECT CARD_USE_FLAG FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_USE_FLAG --36 , ( SELECT CARD_CONFIRM_NO FROM ICOMPRHD PRHD WHERE S.BUYER = PRHD.BUYER AND S.PR_NO = PRHD.PR_NO AND ROWNUM =1 ) AS CARD_CONFIRM_NO -- 37 , S.PX_NO , S.CATEG_ID , S.BUDGET_DEPT , S.ACCOUNT_NAME , S.BUDGET_DEPT_CODE , S.ACCOUNT_TYPE , S.ADD_USER_NAME , S.CATEG_NAME , S.SO_CA_GUBUN , S.RECV_FLAG , S.CLSD_FLAG , S.PCO_REF_PR_NO , S.PCO_LEGACY_PO_NO , S.PR_CHANGE_DATE , S.GR_ADD_USER_ID , S.GR_ADD_USER_NAME , S.SIZE_QTY , S.SIZE_LEN , (SELECT CM.COM_NAME_LOC FROM ICOMCMPY CM WHERE CM.COM_CODE =S.BUYER) COM_NAME_LOC , S.PR_REF_PR_NO0 -- 회계단위 , S.PR_REF_PR_NO1 -- 용도 , S.PR_REF_PR_NO2 -- 코스트센터 , S.PR_REF_PR_NO3 -- 계정 , S.PR_REF_PR_NO4 -- 프로젝트코드 , S.IMAGE_KEY_INV , S.IMAGE_KEY_SIGN , S.PARCEL_INFO , S.AUTO_GR_FLAG , S.WAREHOUSE_CODE , S.SELLER , S.PURCHASER_ID , S.PO_REMARK , S.PH_REMARK , S.PR_USER_NAME , S.DELY_TO_LOCATION FROM ( SELECT DISTINCT DECODE(GR.AR_BILL_FLAG,'Y','마감완료', DECODE((NVL(PO.ITEM_QTY,0) - NVL(PO.GR_QTY,0)),0,'입고완료','부분입고')) AS GR_STATUS , PH.PO_CREATE_DATE , PO.PO_NO , GR.GR_NO , PO.BUYER_ITEM_NO , PO.REF_PR_NO AS REF_PR_NO , PO.DESCRIPTION , PO.SPECIFICATION , PO.UNIT_PRICE , GR.ITEM_AMT , PO.UNIT_MEASURE , PO.ITEM_QTY AS PO_ITEM_QTY , GR.ITEM_QTY AS GR_ITEM_QTY , PO.GR_QTY , GR.GR_DATE , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.PURCHASER_ID) AS PO_CREATOR , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = GR.AGENT AND STATUS !='D') AS AGENT_NAME , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.CHANGE_USER_DEPT AND TYPE = 'C001') AS REQ_DEPT_NAME , GR.GR_SEQ , GR.PO_SEQ , GR.INV_NO , GR.INV_SEQ , DECODE(GR.INV_NO,NULL,'N','Y') AS IV_EXIST , PO.BUYER , PO.BYIT_COMORG_CODE , PO.CONTRACT_NO , PO.CONTRACT_SEQ , PO.PR_NO , PH.AGENT , PR.CHANGE_USER_DEPT , GR.CLOSE_FLAG , GR.AR_BILL_FLAG , PR.REF_NO AS PX_NO , PO.CATEG_ID , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND CODE = PR.BUDGET_DEPT AND TYPE = 'C001') AS BUDGET_DEPT , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE = 'Z014' AND CODE = PR.ACCOUNT_TYPE) AS ACCOUNT_NAME , PR.ACCOUNT_TYPE AS ACCOUNT_TYPE , PR.BUDGET_DEPT AS BUDGET_DEPT_CODE , PR.ADD_USER_NAME , (SELECT CATEG_PATH FROM ICOMBYCA WHERE COM_CODE = PO.BYIT_COMORG_CODE AND STD_CATEG_ID = PO.CATEG_ID) AS CATEG_NAME , DECODE(( SELECT COUNT(*) FROM KEPRQDT WHERE BUYER = PO.BUYER AND BUYER_ITEM_NO = PO.BUYER_ITEM_NO AND SO_CA_FLAG = 'SO' AND STATUS ^='D'), 0, 'CA', 'SO') AS SO_CA_GUBUN , PR.RECV_FLAG , NVL(PO.CLSD_FLAG,'N') AS CLSD_FLAG , PR.REF_PR_NO AS PCO_REF_PR_NO , PO.LEGACY_PO_NO AS PCO_LEGACY_PO_NO , PR.CHANGE_DATE AS PR_CHANGE_DATE , GR.ADD_USER_ID AS GR_ADD_USER_ID , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = GR.ADD_USER_ID) AS GR_ADD_USER_NAME , PR.SIZE_QTY , PR.SIZE_LEN , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C021' AND COMPANY_CODE = PO.BUYER AND CODE = F_SPLIT(PO.REF_PR_NO, '^', 1) AND FLAG = 'Y') AS PR_REF_PR_NO0 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'M014' AND COMPANY_CODE = PO.BUYER AND CODE = F_SPLIT(PO.REF_PR_NO, '^', 2) AND FLAG = 'Y') AS PR_REF_PR_NO1 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C020' AND COMPANY_CODE = PO.BUYER AND CODE = F_SPLIT(PO.REF_PR_NO, '^', 3) AND FLAG = 'Y') AS PR_REF_PR_NO2 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'Z014' AND COMPANY_CODE = PO.BUYER AND CODE = F_SPLIT(PO.REF_PR_NO, '^', 4)) AS PR_REF_PR_NO3 , (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C022' AND COMPANY_CODE = PO.BUYER AND CODE = F_SPLIT(PO.REF_PR_NO, '^', 5) AND FLAG = 'Y') AS PR_REF_PR_NO4 , CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT IVHD.IMAGE_KEY_INV FROM ICOMIVHD IVHD WHERE IVHD.BUYER = GR.BUYER AND IVHD.INV_NO = GR.INV_NO AND IVHD.STATUS != 'D') ELSE (SELECT WMS.IMAGE_KEY_INV FROM WMSIVDT WMS WHERE WMS.BUYER = GR.BUYER AND WMS.INV_NO = GR.INV_NO AND WMS.INV_SEQ = GR.INV_SEQ AND WMS.STATUS != 'D') END AS IMAGE_KEY_INV , CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT IVHD.IMAGE_KEY_SIGN FROM ICOMIVHD IVHD WHERE IVHD.BUYER = GR.BUYER AND IVHD.INV_NO = GR.INV_NO AND IVHD.STATUS != 'D') ELSE (SELECT WMS.IMAGE_KEY_SIGN FROM WMSIVDT WMS WHERE WMS.BUYER = GR.BUYER AND WMS.INV_NO = GR.INV_NO AND WMS.INV_SEQ = GR.INV_SEQ AND WMS.STATUS != 'D') END AS IMAGE_KEY_SIGN , CASE WHEN PO.PROCESS_TYPE = '0' THEN (SELECT F_GET_CMCD_NAME('C019', IVHD.PARCEL_COM_CODE) FROM ICOMIVHD IVHD WHERE IVHD.BUYER = GR.BUYER AND IVHD.INV_NO = GR.INV_NO AND IVHD.STATUS != 'D') ELSE (SELECT F_GET_CMCD_NAME('C019', WMS.DELIVERY_COMPANY) FROM WMSIVDT WMS WHERE WMS.BUYER = GR.BUYER AND WMS.INV_NO = GR.INV_NO AND WMS.INV_SEQ = GR.INV_SEQ AND WMS.STATUS != 'D') END AS PARCEL_INFO , NVL(BUYER.AUTO_GR_FLAG, 'N') AS AUTO_GR_FLAG , GR.SELLER AS SELLER , PO.WAREHOUSE_CODE AS WAREHOUSE_CODE , PH.PURCHASER_ID AS PURCHASER_ID , PO.PO_REMARK , PH.PO_REMARK AS PH_REMARK , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = PR.ADD_USER_ID) AS PR_USER_NAME , PH.DELY_TO_LOCATION FROM ICOMPODT PO, ICOMPOHD PH, ICOMGRDT GR, ICOMPRDT PR, KEP_BUYER_FLAG BUYER WHERE 1=1
AND GR.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'BGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.TEXT1 = #{st_group_info} AND COD3.FLAG = 'Y')
AND GR.BUYER = #{st_com_code}
AND GR.BUYER IN (SELECT COD3.CODE2 FROM ICOMCOD3 COD3 WHERE COD3.TYPE = 'TGCM' AND COD3.CODE1 = #{st_user_id} AND COD3.FLAG = 'Y')
AND GR.BUYER = #{st_com_code}
AND GR.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND PR.CHANGE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND (PO.REF_PR_NO LIKE #{st_ref_pr_no}||'%' OR PO.LEGACY_PO_NO LIKE #{st_ref_pr_no}||'%')
AND PR.ACCOUNT_TYPE = #{st_acnt_cd}
AND PO.LEGACY_PO_NO LIKE #{st_legacy_po_no}||'%'
AND UPPER( PR.BUYER_ITEM_NO) LIKE UPPER(#{st_buyer_item_no}||'%')
AND PR.CHANGE_USER_ID = #{st_change_user_id}
AND PR.PURCHASER_DEPT = #{st_req_dept_code}
AND PR.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PR.BUDGET_DEPT = #{st_req_dept_code}
AND EXISTS ( SELECT 'X' FROM ICOMIVDT IV, WMSIVDT WMS WHERE IV.BUYER = PO.BUYER AND IV.PO_NO = PO.PO_NO AND IV.PO_SEQ= PO.PO_SEQ AND IV.STATUS != 'D' AND IV.BUYER = WMS.BUYER(+) AND IV.PO_NO = WMS.PO_NO(+) AND IV.PO_SEQ= WMS.PO_SEQ(+) AND IV.INV_NO = WMS.S_INV_NO(+) AND IV.INV_SEQ= WMS.S_INV_SEQ(+) AND WMS.STATUS(+) <> 'D' AND DECODE(PO.PROCESS_TYPE,'0',IV.INV_NO, WMS.INV_NO ) LIKE UPPER('%'||#{st_search_no}||'%'))
AND PR.PR_NO LIKE UPPER(#{st_search_no}||'%')
AND PO.PO_NO LIKE UPPER(#{st_search_no}||'%')
AND PR.PURCHASER_ID = #{st_po_user_id}
AND PR.ADD_USER_ID = #{st_po_user_id}
AND GR.BUYER_ITEM_NO LIKE '%'||#{st_search_buyer_item_no}||'%'
AND (GR.DESCRIPTION LIKE '%'||#{st_search_desc_spec}||'%' OR GR.SPECIFICATION LIKE '%'||#{st_search_desc_spec}||'%')
AND GR.AGENT IN (SELECT COM_CODE FROM ICOMCMPY WHERE COM_NAME_LOC LIKE '%'||#{st_search_agent}||'%' AND STATUS IN ('C','R') AND BUSINESS_COND='S')
AND PO.BUYER = PH.BUYER AND PO.PO_NO = PH.PO_NO AND PO.BUYER = GR.BUYER AND PO.PO_NO = GR.PO_NO AND PO.PO_SEQ = GR.PO_SEQ AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND PO.BUYER = BUYER.COM_CODE(+) AND PO.STATUS <>'D' AND PH.STATUS <>'D' AND GR.STATUS <>'D' AND PR.STATUS <>'D' ORDER BY PO.PO_NO, GR.GR_NO, GR.GR_SEQ ) S

/*selectHLCERPList*/ select 'KEP'||TO_CHAR(SYSDATE,'YYYYMMDD')||TO_CHAR(dense_rank() over(order by tax_bill_no ),'FM00000') AS ROW_ID , row_number() over(partition by tax_bill_no order by tax_bill_no,au,ct,cc,at) AS ROW_NO , DECODE(seq_no,2,'1','*') AS NO_TAX , AU AS CD_PC , y.DEPARTMENT AS CD_WDEPT -- , (SELECT TEXT4 FROM ICOMCOD2 -- WHERE COMPANY_CODE = Z.COM_CODE -- AND TYPE = 'C001' -- AND CODE = Z.DEPARTMENT) AS CD_WDEPT , 'KEP'||TO_CHAR(SYSDATE,'YYYYMMDD')||TO_CHAR(dense_rank() over(order by tax_bill_no ),'FM00000') AS NO_DOCU , row_number() over(partition by tax_bill_no order by tax_bill_no,au,ct,cc,at) AS NO_DOLINE , '1000' AS CD_COMPANY , y.LEGACY_USER_ID AS ID_WRITE , '11' AS CD_DOCU , TO_CHAR(LAST_DAY(TO_DATE(X.CLOSE_DATE,'YYYYMMDD')),'YYYYMMDD') AS DT_ACCT , '1' AS ST_DOCU , DECODE(seq_no,3,'2','1') AS TP_DRCR , at AS CD_ACCT , x.ITEM_AMT AS AMT , '142736' AS CD_PARTNER , DECODE(seq_no,2,TO_CHAR(LAST_DAY(TO_DATE(X.CLOSE_DATE,'YYYYMMDD')),'YYYYMMDD'),NULL) AS DT_START , NULL AS DT_END , DECODE(seq_no,2,X.TOT_AMT,NULL) AS AM_TAXSTD , DECODE(seq_no,2,X.ITEM_AMT,NULL) AS AM_ADDTAX , DECODE(seq_no,2,'21',NULL ) AS TP_TAX , DECODE(seq_no,2,'1078185880',NULL ) AS NO_COMPANY , 'MRO 물품구입' AS NM_NOTE , DECODE(seq_no,2,'1000',NULL ) AS CD_BIZAREA , NULL AS CD_DEPT , DECODE(seq_no,1,X.CC,NULL) AS CD_CC , X.PT AS CD_PJT , NULL AS CD_FUND , NULL AS CD_BUDGET , NULL AS NO_CASH , NULL AS ST_MUTUAL , NULL AS CD_CARD , NULL AS NO_DEPOSIT , NULL AS CD_BANK , NULL AS UCD_MNG1 , NULL AS UCD_MNG2 , NULL AS UCD_MNG3 , NULL AS UCD_MNG4 , NULL AS UCD_MNG5 , NULL AS CD_EMPLOY , NULL AS CD_MNG , NULL AS NO_BDOCU , NULL AS NO_BDOLINE , 'N' AS TP_DOCU , '0' AS NO_ACCT , NULL AS TP_TRADE , NULL AS NO_CHECK3 , NULL AS NO_CHECK4 , NULL AS CD_EXCH , NULL AS RT_EXCH , NULL AS CD_TRADE , NULL AS AM_EX , NULL AS TP_EXPORT , NULL AS NO_TO , NULL AS DT_SHIPPING , '3' AS TP_GUBUN , NULL AS NO_INVOICE , NULL AS NO_ITEM , NULL AS MD_TAX1 , NULL AS NM_ITEM1 , NULL AS NM_SIZE1 , NULL AS QT_TAX1 , NULL AS AM_PRC1 , NULL AS AM_SUPPLY1 , NULL AS AM_TAX1 , NULL AS NM_NOTE1 , NULL AS CD_BIZPLAN , NULL AS CD_BGACCT , NULL AS CD_MNGD1 , NULL AS NM_MNGD1 , NULL AS CD_MNGD2 , NULL AS NM_MNGD2 /* 선택한 계정구분 그대로 표기 없으면 공통으로 */ , NVL(X.CT, '3') AS CD_MNGD3 , NVL((SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'M014' AND COMPANY_CODE = 'KRHANC0020' AND CODE = X.CT), '공통') AS NM_MNGD3 , NULL AS CD_MNGD4 , NULL AS NM_MNGD4 , NULL AS CD_MNGD5 , NULL AS NM_MNGD5 , NULL AS CD_MNGD6 , NULL AS NM_MNGD6 , NULL AS CD_MNGD7 , NULL AS NM_MNGD7 , NULL AS CD_MNGD8 , NULL AS NM_MNGD8 , NULL AS YN_ISS , NULL AS FINAL_STATUS , NULL AS NO_BILL , NULL AS NM_BIGO , NULL AS TP_BILL , NULL AS TP_RECORD , NULL AS TP_ETCACCT , NULL AS ST_GWARE , NULL AS SELL_DAM_NM , NULL AS SELL_DAM_EMAIL , NULL AS SELL_DAM_MOBIL , NULL AS SELL_DAM_TEL , NULL AS NM_PUMM , NULL AS JEONJASEND15_YN , NULL AS DT_WRITE , NULL AS ST_TAX , NULL AS MD_TAX2 , NULL AS NM_ITEM2 , NULL AS NM_SIZE2 , NULL AS QT_TAX2 , NULL AS AM_PRC2 , NULL AS AM_SUPPLY2 , NULL AS AM_TAX2 , NULL AS NM_NOTE2 , NULL AS MD_TAX3 , NULL AS NM_ITEM3 , NULL AS NM_SIZE3 , NULL AS QT_TAX3 , NULL AS AM_PRC3 , NULL AS AM_SUPPLY3 , NULL AS AM_TAX3 , NULL AS NM_NOTE3 , NULL AS MD_TAX4 , NULL AS NM_ITEM4 , NULL AS NM_SIZE4 , NULL AS QT_TAX4 , NULL AS AM_PRC4 , NULL AS AM_SUPPLY4 , NULL AS AM_TAX4 , NULL AS NM_NOTE4 , NULL AS NM_PTR , NULL AS EX_HP , NULL AS EX_EMIL , NULL AS NO_BIZTAX , NULL AS NO_ASSET , '3' AS TP_EVIDENCE , NULL AS NO_CAR , NULL AS NO_CARBODY , NULL AS CD_BIZCAR , NULL AS NM_PARTNER , NULL AS YN_IMPORT , NULL AS YN_FIXASSET from ( SELECT 1 as seq_no , nvl(ar_tax_bill_no,'AR23000') as tax_bill_no , F_SPLIT(PODT.REF_PR_NO,'^',1) AS AU , F_SPLIT(PODT.REF_PR_NO,'^',2) AS CT , F_SPLIT(PODT.REF_PR_NO,'^',3) AS CC , F_SPLIT(PODT.REF_PR_NO,'^',4) AS AT , F_SPLIT(PODT.REF_PR_NO,'^',5) AS PT , SUM(GRDT.ITEM_AMT) AS ITEM_AMT , MAX(SUBSTR(GR_DATE,1,8)) AS CLOSE_DATE , SUM(GRDT.ITEM_AMT) AS TOT_AMT FROM ICOMGRDT GRDT, ICOMPODT PODT WHERE GRDT.BUYER = 'KRHANC0020' AND GRDT.STATUS IN ('C','R') AND GRDT.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GRDT.BUYER = PODT.BUYER AND GRDT.PO_NO = PODT.PO_NO AND GRDT.PO_SEQ= PODT.PO_SEQ GROUP BY nvl(ar_tax_bill_no,'AR23000') , F_SPLIT(PODT.REF_PR_NO,'^',1) , F_SPLIT(PODT.REF_PR_NO,'^',2) , F_SPLIT(PODT.REF_PR_NO,'^',3) , F_SPLIT(PODT.REF_PR_NO,'^',4) , F_SPLIT(PODT.REF_PR_NO,'^',5)
union
SELECT 2 as seq_no , nvl(ar_tax_bill_no,'AR23000') as tax_bill_no /*용기재검사소 계산서 발행건은 9000, 본사는 1000 (사업자번호 변경되면 수정 필요) */ , (SELECT DECODE(MAX(IRS_NO), '325-85-02340', '9000', '135-81-21955', '1000', '1000') FROM KEPTARDT WHERE TAX_BILL_NO = GRDT.AR_TAX_BILL_NO) AS AU , null AS CT , null AS CC , '12400' AS AT , null AS PT , SUM(GRDT.ITEM_AMT)/10 AS ITEM_AMT , MAX(SUBSTR(GR_DATE,1,8)) AS CLOSE_DATE , SUM(GRDT.ITEM_AMT) AS TOT_AMT FROM ICOMGRDT GRDT, ICOMPODT PODT WHERE GRDT.BUYER = 'KRHANC0020' AND GRDT.STATUS IN ('C','R') AND GRDT.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GRDT.BUYER = PODT.BUYER AND GRDT.PO_NO = PODT.PO_NO AND GRDT.PO_SEQ= PODT.PO_SEQ GROUP BY nvl(ar_tax_bill_no,'AR23000'), GRDT.AR_TAX_BILL_NO
union
SELECT 3 as seq_no , nvl(ar_tax_bill_no,'AR23000') as tax_bill_no /*용기재검사소 계산서 발행건은 9000, 본사는 1000 (사업자번호 변경되면 수정 필요) */ , (SELECT DECODE(MAX(IRS_NO), '325-85-02340', '9000', '135-81-21955', '1000', '1000') FROM KEPTARDT WHERE TAX_BILL_NO = GRDT.AR_TAX_BILL_NO) AS AU , null AS CT , null AS CC , '30302' AS AT , null AS PT , (SUM(GRDT.ITEM_AMT) + SUM(GRDT.ITEM_AMT)/10) AS ITEM_AMT , MAX(SUBSTR(GR_DATE,1,8)) AS CLOSE_DATE , SUM(GRDT.ITEM_AMT) AS TOT_AMT FROM ICOMGRDT GRDT, ICOMPODT PODT WHERE GRDT.BUYER = 'KRHANC0020' AND GRDT.STATUS IN ('C','R') AND GRDT.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GRDT.BUYER = PODT.BUYER AND GRDT.PO_NO = PODT.PO_NO AND GRDT.PO_SEQ= PODT.PO_SEQ GROUP BY nvl(ar_tax_bill_no,'AR23000'), GRDT.AR_TAX_BILL_NO ) x, icomlusr y WHERE y.USER_ID = #{st_user_id}

/* selectBuyerWmGrWarehousingAmoreLisList */ SELECT 회사코드, MAX(변경주문일자) AS 변경주문일자, 주문번호, 주문항번, MAX(변경입고일자) AS 변경입고일자, 입고번호, 품목코드, MAX(통화키) AS 통화키, SUM(주문수량) AS 주문수량, MAX(판매단가) AS 판매단가, SUM(판매금액) aS 판매금액, MAX(주문자명) AS 주문자명, MAX(인수자명) AS 인수자명, MAX(공급업체또는채권자의계정번호) AS공급업체또는채권자의계정번호, MAX(부서코드) AS 부서코드, MAX(코스트센터) AS 코스트센터, MAX(자금관리센터) AS 자금관리센터, MAX(계정) AS 계정, MAX(WBS) AS WBS, MAX(비고) AS 비고, MAX(buyer) AS buyer FROM ( SELECT (SELECT SUBSTR(CODE,1,4) FROM ICOMCOD2 -- 마감 대상 WHERE COMPANY_CODE = 'KRAMORG001' AND TYPE = 'PLNT' AND TEXT1 = PRDT.BUYER) AS 회사코드 , PRDT.ADD_DATE AS "변경주문일자" , IF.PR_NO AS "주문번호" , IF.PR_SEQ AS "주문항번" , GRDT.GR_DATE AS "변경입고일자" , GRDT.GR_NO AS "입고번호" , PRDT.BUYER_ITEM_NO AS "품목코드" , 'KRW' AS 통화키 , GRDT.ITEM_QTY AS "주문수량" , PODT.UNIT_PRICE AS "판매단가" , GRDT.ITEM_AMT AS 판매금액 , PRDT.ADD_USER_NAME AS 주문자명 , NVL(F_SPLIT(PRDT.REQ_USER_INFO,' ',1),PRDT.ADD_USER_NAME) AS 인수자명 , '' AS "공급업체또는채권자의계정번호" , DECODE(PRDT.BUYER,'KRAMOR0005',PRDT.ACCOUNT_TYPE,PRDT.ADD_USER_DEPT) AS "부서코드" , PRDT.BUDGET_DEPT AS 코스트센터 , COD2.TEXT3 AS "자금관리센터" , CASE PRDT.BUYER WHEN 'KRAMOR0005' THEN F_SPLIT(PRDT.REF_PR_NO,'-',1) ELSE PRDT.ACCOUNT_TYPE END AS 계정 , DECODE(PRDT.BUYER,'KRAMOR0005',NULL,PRDT.REF_PR_NO) AS "WBS" , '' AS 비고 , prdt.buyer FROM ICOMPRDT PRDT, EAI.IF_UCUBE_PR_SEND IF, ICOMCOD2 COD2, ICOMGRDT GRDT, ICOMPODT PODT WHERE PRDT.BUYER IN (SELECT COM_CODE FROM ICOMCMPY WHERE BYCA_COMORG_CODE = 'KRAMORG001') AND PRDT.ADD_DATE >= '20250701' AND PRDT.STATUS != 'D' AND PRDT.BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE = PRDT.ADD_USER_DEPT AND PRDT.BUYER = IF.BUYER AND PRDT.REF_NO = IF.DOC_NO AND PRDT.REF_SEQ= IF.DOC_SEQ AND PRDT.BUYER = PODT.BUYER AND PRDT.PR_NO = PODT.PR_NO AND PRDT.PR_SEQ= PODT.PR_SEQ AND PODT.STATUS != 'D' AND PODT.BUYER = GRDT.BUYER AND PODT.PO_NO = GRDT.PO_NO AND PODT.PO_SEQ= GRDT.PO_SEQ AND GRDT.STATUS != 'D' AND GRDT.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date}
UNION SELECT (SELECT SUBSTR(CODE,1,4) FROM ICOMCOD2 -- 미마감 WHERE COMPANY_CODE = 'KRAMORG001' AND TYPE = 'PLNT' AND TEXT1 = PRDT.BUYER) AS 회사코드 , PRDT.ADD_DATE AS "변경주문일자" , IF.PR_NO AS "주문번호" , IF.PR_SEQ AS "주문항번" , NULL AS "변경입고일자" , NULL AS "입고번호" , PRDT.BUYER_ITEM_NO AS "품목코드" , 'KRW' AS 통화키 , PODT.ITEM_QTY AS "주문수량" , PODT.UNIT_PRICE AS "판매단가" , PODT.ITEM_AMT AS 판매금액 , PRDT.ADD_USER_NAME AS 주문자명 , NVL(F_SPLIT(PRDT.REQ_USER_INFO,' ',1),PRDT.ADD_USER_NAME) AS 인수자명 , '' AS "공급업체또는채권자의계정번호" , DECODE(PRDT.BUYER,'KRAMOR0005',PRDT.ACCOUNT_TYPE,PRDT.ADD_USER_DEPT) AS "부서코드" , PRDT.BUDGET_DEPT AS 코스트센터 , COD2.TEXT3 AS "자금관리센터" , CASE PRDT.BUYER WHEN 'KRAMOR0005' THEN F_SPLIT(PRDT.REF_PR_NO,'-',1) ELSE PRDT.ACCOUNT_TYPE END AS 계정 , DECODE(PRDT.BUYER,'KRAMOR0005',NULL,PRDT.REF_PR_NO) AS "WBS" , '' AS 비고 , prdt.buyer FROM ICOMPRDT PRDT, EAI.IF_UCUBE_PR_SEND IF, ICOMCOD2 COD2, ICOMPODT PODT WHERE PRDT.BUYER IN (SELECT COM_CODE FROM ICOMCMPY WHERE BYCA_COMORG_CODE = 'KRAMORG001') AND PRDT.ADD_DATE >= '20250701' AND PRDT.STATUS != 'D' AND PRDT.BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE = PRDT.ADD_USER_DEPT AND PRDT.BUYER = IF.BUYER AND PRDT.REF_NO = IF.DOC_NO AND PRDT.REF_SEQ= IF.DOC_SEQ AND PRDT.BUYER = PODT.BUYER AND PRDT.PR_NO = PODT.PR_NO AND PRDT.PR_SEQ= PODT.PR_SEQ AND PODT.STATUS != 'D' AND NOT EXISTS (SELECT 'X' FROM ICOMGRDT WHERE STATUS != 'D' AND BUYER = PODT.BUYER AND PO_NO = PODT.PO_NO AND PO_SEQ= PODT.PO_SEQ AND GR_DATE <= #{st_to_date} -- AND ITEM_QTY=PODT.ITEM_QTY )
UNION SELECT (SELECT SUBSTR(CODE,1,4) FROM ICOMCOD2 -- 반품 WHERE COMPANY_CODE = 'KRAMORG001' AND TYPE = 'PLNT' AND TEXT1 = A.BUYER) AS 회사코드 , (SELECT PRDT.ADD_DATE FROM IF_UCUBE_PR_SEND IF, ICOMPRDT PRDT, ICOMPODT PODT WHERE PODT.BUYER = C.BUYER AND PODT.PO_NO = F_SPLIT(C.CANCEL_REMARK,'/',1) AND PODT.PO_SEQ = F_SPLIT(C.CANCEL_REMARK,'/',2) AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ= PRDT.PR_SEQ AND PRDT.BUYER = IF.BUYER AND PRDT.REF_NO= IF.DOC_NO AND PRDT.REF_SEQ= IF.DOC_SEQ) AS "변경주문일자" , (SELECT IF.PR_NO FROM IF_UCUBE_PR_SEND IF, ICOMPRDT PRDT, ICOMPODT PODT WHERE PODT.BUYER = C.BUYER AND PODT.PO_NO = F_SPLIT(C.CANCEL_REMARK,'/',1) AND PODT.PO_SEQ = F_SPLIT(C.CANCEL_REMARK,'/',2) AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ= PRDT.PR_SEQ AND PRDT.BUYER = IF.BUYER AND PRDT.REF_NO= IF.DOC_NO AND PRDT.REF_SEQ= IF.DOC_SEQ) AS "주문번호" , (SELECT IF.PR_SEQ FROM IF_UCUBE_PR_SEND IF, ICOMPRDT PRDT, ICOMPODT PODT WHERE PODT.BUYER = C.BUYER AND PODT.PO_NO = F_SPLIT(C.CANCEL_REMARK,'/',1) AND PODT.PO_SEQ = F_SPLIT(C.CANCEL_REMARK,'/',2) AND PODT.BUYER = PRDT.BUYER AND PODT.PR_NO = PRDT.PR_NO AND PODT.PR_SEQ= PRDT.PR_SEQ AND PRDT.BUYER = IF.BUYER AND PRDT.REF_NO= IF.DOC_NO AND PRDT.REF_SEQ= IF.DOC_SEQ) AS "주문항번" , c.add_DATE AS "변경입고일자" , A.GR_NO AS "입고번호" , A.BUYER_ITEM_NO AS "품목코드" , 'KRW' AS 통화키 , A.ITEM_QTY AS "주문수량" , A.UNIT_PRICE AS "판매단가" , A.ITEM_AMT AS 판매금액 , C.ADD_USER_NAME AS 주문자명 , NVL(F_SPLIT(C.REQ_USER_INFO,' ',1),C.ADD_USER_NAME) AS 인수자명 , '' AS "공급업체또는채권자의계정번호" , DECODE(C.BUYER,'KRAMOR0005',C.ACCOUNT_TYPE,C.ADD_USER_DEPT) AS "부서코드" , C.BUDGET_DEPT AS 코스트센터 , COD2.TEXT3 AS "자금관리센터" , CASE C.BUYER WHEN 'KRAMOR0005' THEN F_SPLIT(C.REF_PR_NO,'-',1) ELSE C.ACCOUNT_TYPE END AS 계정 , DECODE(C.BUYER,'KRAMOR0005',NULL,C.REF_PR_NO) AS "WBS" , '' AS 비고 , C.buyer FROM icomgrdt a, icompodt b, icomprdt c, ICOMCOD2 COD2 WHERE a.BUYER IN (SELECT COM_CODE FROM ICOMCMPY WHERE BYCA_COMORG_CODE = 'KRAMORG001') and a.item_qty < 0 and a.gr_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND A.PO_SEQ= B.PO_SEQ AND B.BUYER = C.BUYER AND B.PR_NO = C.PR_NO AND B.PR_SEQ= C.PR_SEQ AND C.BUYER = COD2.COMPANY_CODE AND COD2.TYPE = 'C001' AND COD2.CODE = C.ADD_USER_DEPT ) GROUP BY 회사코드,주문번호,주문항번,입고번호,품목코드 ORDER BY 1,2,3,4

/* selectBuyerWmGrWarehousingKleannaraList */ SELECT GR.BUYER, GR.PO_NO, GR.PO_SEQ, GR.PO_NO||'-'||TO_CHAR(GR.PO_SEQ, '000000') AS PO_NO_SEQ, DECODE(GR.AR_BILL_FLAG,'Y','마감완료', DECODE((NVL(PO.ITEM_QTY,0) - NVL(PO.GR_QTY,0)),0,'입고완료','부분입고')) AS GR_STATUS, GR.BUYER_ITEM_NO, PO.DESCRIPTION, PO.SPECIFICATION, GR.ITEM_QTY, GR.UNIT_MEASURE, GR.UNIT_PRICE, GR.ITEM_AMT, GR.ITEM_AMT * 0.1 AS TAX_AMT, PR.REQ_DEPT, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = GR.BUYER AND CODE = PR.REQ_DEPT) AS REQ_DEPT_NAME, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.REQ_USER_ID) AS REQ_USER_NAME, (SELECT PO_REMARK FROM ICOMPOHD WHERE BUYER = GR.BUYER AND PO_NO = GR.PO_NO) AS PO_REMARK, PR.RECIPIENT_NAME, TO_CHAR(TO_DATE(PR.ADD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS PR_ADD_DATE, TO_CHAR(TO_DATE(PO.ADD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS PO_ADD_DATE, DECODE(PO.PROCESS_TYPE, '0', (SELECT TO_CHAR(TO_DATE(DELIVERY_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') FROM ICOMIVDT WHERE BUYER = GR.BUYER AND INV_NO = GR.INV_NO AND INV_SEQ = GR.INV_SEQ AND STATUS <> 'D'), (SELECT TO_CHAR(TO_DATE(DELIVERY_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') FROM WMSIVDT WHERE BUYER = GR.BUYER AND INV_NO = GR.INV_NO AND INV_SEQ = GR.INV_SEQ AND STATUS <> 'D')) AS DELIVERY_DATE, PR.REQ_DEPT AS REQ_DEPT2, (SELECT TEXT1 FROM ICOMCOD2 WHERE TYPE = 'C001' AND COMPANY_CODE = GR.BUYER AND CODE = PR.REQ_DEPT) AS REQ_DEPT_NAME2, PR.ACCOUNT_TYPE AS ACCOUNT_CODE, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE = 'Z014' AND CODE = PR.ACCOUNT_TYPE) AS ACCOUNT_NAME, '' AS REQ_DEPT3, '' AS REQ_DEPT_NAME3, PR.BUDGET_DEPT AS COST_CENTER_CODE, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = PR.BUYER AND TYPE = 'C001' AND CODE = PR.BUDGET_DEPT) AS COST_CENTER_NAME, '' AS PLANT, '' AS NULL_VALUE1, '' AS NULL_VALUE2 FROM ICOMGRDT GR, ICOMPODT PO, ICOMPRDT PR WHERE 1=1 AND GR.BUYER = PO.BUYER AND GR.PO_NO = PO.PO_NO AND GR.PO_SEQ = PO.PO_SEQ AND PO.BUYER = PR.BUYER AND PO.PR_NO = PR.PR_NO AND PO.PR_SEQ = PR.PR_SEQ AND GR.STATUS <> 'D' AND PO.STATUS <> 'D' AND PR.STATUS <> 'D' AND GR.GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND GR.BUYER = #{st_com_code}
AND PO.REF_PR_NO LIKE '%' || #{st_ref_pr_no} || '%'
AND PR.ACCOUNT_TYPE = #{st_acnt_cd}
AND PR.PURCHASER_DEPT = #{st_req_dept_code}
AND PR.CHANGE_USER_DEPT = #{st_req_dept_code}
AND PR.BUDGET_DEPT = #{st_req_dept_code}
AND EXISTS ( SELECT 'X' FROM ICOMIVDT IV, WMSIVDT WMS WHERE IV.BUYER = PO.BUYER AND IV.PO_NO = PO.PO_NO AND IV.PO_SEQ = PO.PO_SEQ AND IV.STATUS != 'D' AND IV.BUYER = WMS.BUYER(+) AND IV.PO_NO = WMS.PO_NO(+) AND IV.PO_SEQ = WMS.PO_SEQ(+) AND IV.INV_NO = WMS.S_INV_NO(+) AND IV.INV_SEQ = WMS.S_INV_SEQ(+) AND WMS.STATUS(+) <> 'D' AND DECODE(PO.PROCESS_TYPE, '0', IV.INV_NO, WMS.INV_NO) LIKE UPPER('%' || #{st_search_no} || '%') )
AND PR.PR_NO LIKE UPPER('%' || #{st_search_no} || '%')
AND PO.PO_NO LIKE UPPER('%' || #{st_search_no} || '%')
AND PR.PURCHASER_ID = #{st_po_user_id}
AND PR.ADD_USER_ID = #{st_po_user_id}
AND GR.AR_BILL_FLAG = 'Y'
AND GR.AR_BILL_FLAG = 'N' AND (NVL(PO.ITEM_QTY,0) - NVL(PO.GR_QTY,0)) = 0
AND GR.AR_BILL_FLAG = 'N' AND (NVL(PO.ITEM_QTY,0) - NVL(PO.GR_QTY,0)) ^= 0
AND GR.BUYER_ITEM_NO LIKE '%'||#{st_search_buyer_item_no}||'%'
AND (GR.DESCRIPTION LIKE '%'||#{st_search_desc_spec}||'%' OR GR.SPECIFICATION LIKE '%'||#{st_search_desc_spec}||'%')
AND GR.AGENT IN (SELECT COM_CODE FROM ICOMCMPY WHERE COM_NAME_LOC LIKE '%'||#{st_search_agent}||'%' AND STATUS IN ('C','R') AND BUSINESS_COND='S')
AND GR.BUYER_ITEM_NO LIKE '%'||#{st_search_no2}||'%'
AND GR.DESCRIPTION LIKE '%'||#{st_search_no2}||'%'
AND GR.SPECIFICATION LIKE '%'||#{st_search_no2}||'%'
